insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('critical-thinking-depth', 'Critical Thinking Depth', 'Evaluate arguments for hidden assumptions, unstated premises, and reasoning under incomplete information.', 'Critical Thinking Depth is built around the five-skill structure of the Watson-Glaser Critical Thinking Appraisal (Watson & Glaser, 1925 onward' || chr(59) || ' still one of the most widely used critical-thinking measures in professional and legal hiring): Inference, Recognition of Assumptions, Deduction, Interpretation, and Evaluation of Arguments. Each section isolates one skill so the results show exactly where your reasoning is strong versus where it slips.', 'layers', (select id from assessment_categories where key = 'logical'), ('standard_questionnaire')::assessment_engine_type, ('hard')::assessment_difficulty, 20, 20, false, ('free')::assessment_access, ('published')::assessment_status)
insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values ((select id from assessments where slug = 'critical-thinking-depth'), 'critical-thinking', 'Critical Thinking', 'Composite score across all five Watson-Glaser skills.', true, 'logical', 1)
insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values ((select id from assessments where slug = 'critical-thinking-depth'), 'inference', 'Inference', 'Judging the truth-value of conclusions from stated facts alone.', false, NULL, 2)
