insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values ((select id from assessments where slug = 'critical-thinking-depth'), 'argument-evaluation', 'Evaluation of Arguments', 'Telling strong, relevant arguments from weak or irrelevant ones.', false, NULL, 6)
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'critical-thinking-depth'), 'overall', 0, 30, 'Developing', 'Critical-thinking fundamentals are still forming — conclusions are often accepted or rejected based on plausibility rather than what the evidence actually supports.', ARRAY['Practice separating ''stated'' from ''assumed'' in everyday arguments you read', 'Work through simple syllogisms and check your answer against formal validity, not intuition', 'When reading an argument, explicitly list the unstated assumptions it depends on']::text[], NULL, 1);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'critical-thinking-depth'), 'overall', 31, 50, 'Average', 'Solid on straightforward inference and deduction, but multi-step arguments or subtle unstated assumptions still catch you out.', ARRAY['Practice the ''must be true vs. might be true vs. cannot be determined'' distinction deliberately', 'Read opinion pieces and identify the strongest counter-argument before evaluating the author''s case', 'Slow down on assumption-recognition items — the obvious-sounding option is often a distractor']::text[], NULL, 2);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'critical-thinking-depth'), 'overall', 51, 70, 'Strong', 'Consistently separates valid inference from plausible-sounding speculation, and generally spots the argument''s real weak point.', ARRAY['Practice evaluating arguments on relevance and importance, not just whether you agree with the conclusion', 'Seek out longer, multi-premise deductive chains to sharpen precision']::text[], NULL, 3);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'critical-thinking-depth'), 'overall', 71, 85, 'Very Strong', 'Reliably distinguishes valid reasoning from rhetoric across all five skills, rarely swayed by an argument''s conclusion when judging its structure.', ARRAY['Apply this discipline to real decisions with incomplete information — write out the inference chain explicitly', 'Practice constructing counter-arguments that meet the same evaluation-of-arguments bar you hold others to']::text[], NULL, 4);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'critical-thinking-depth'), 'overall', 86, 100, 'Exceptional', 'Expert-level critical thinking — evidence, assumptions, and validity are evaluated independently of what conclusion is more comfortable or expected.', ARRAY['This is the skill set legal, analytical, and research roles are built on — consider where it''s most leveraged', 'Mentor others on the difference between a strong argument and one that merely sounds confident']::text[], NULL, 5);
